// Build Claude API request with vision content blocks
const body = $input.first().json.body;
const photos = body.photos || [];
const trade = body.trade || 'tradesperson';

if (photos.length === 0) {
  return [{ json: { error: 'No photos provided' } }];
}

// Build content array with images + text prompt
const content = [];

// Add each photo as an image content block
for (const photo of photos) {
  // photo is a base64 data URL like "data:image/jpeg;base64,/9j/4AAQ..."
  const matches = photo.match(/^data:(image\/\w+);base64,(.+)$/);
  if (matches) {
    content.push({
      type: 'image',
      source: {
        type: 'base64',
        media_type: matches[1],
        data: matches[2]
      }
    });
  }
}

// Add the extraction prompt
content.push({
  type: 'text',
  text: `You are an expert at extracting quote and invoice data from photos. The user is a ${trade} in New Zealand.

Analyse the photo(s) of a quote/invoice and extract ALL details you can find. Return a JSON object with this exact structure:

{
  "job_title": "Brief job title (e.g. Bathroom Renovation, Roof Repair)",
  "description": "Full scope of work / job description extracted from the quote",
  "amount": 0,
  "customer_name": "Customer name if visible",
  "status": "booked",
  "line_items": [
    { "description": "Item description", "amount": 0 }
  ]
}

Rules:
- "amount" should be the TOTAL excl. GST. If the quote shows GST-inclusive pricing, divide by 1.15 to get excl. GST.
- If you can see individual line items (materials, labour, etc.), include them in "line_items"
- If you can't determine the customer name, use an empty string
- "status" should be "booked" (assume completed work) unless the quote clearly shows it was declined
- Be accurate with dollar amounts — don't round unless the original is rounded
- If you can't extract meaningful data, return { "error": "Could not read quote details from this image" }

Return ONLY valid JSON, no markdown, no explanation.`
});

return [{
  json: {
    requestBody: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 2000,
      messages: [
        {
          role: 'user',
          content: content
        }
      ]
    }
  }
}];

// Parse Claude API response and extract the JSON
const response = $input.first().json;

try {
  // Claude API returns { content: [{ type: 'text', text: '...' }] }
  const text = response.content?.[0]?.text || '';

  if (!text) {
    return [{ json: { error: 'Empty response from AI' } }];
  }

  // Extract JSON (handle markdown code blocks just in case)
  let jsonStr = text.trim();
  if (jsonStr.includes('```')) {
    jsonStr = jsonStr.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  }

  const extracted = JSON.parse(jsonStr);

  // Check for error response
  if (extracted.error) {
    return [{ json: { error: extracted.error } }];
  }

  // Ensure amount is a number
  extracted.amount = parseFloat(extracted.amount) || 0;

  // Ensure line_items amounts are numbers
  if (extracted.line_items && Array.isArray(extracted.line_items)) {
    extracted.line_items = extracted.line_items.map(item => ({
      description: item.description || '',
      amount: parseFloat(item.amount) || 0
    }));
  } else {
    extracted.line_items = [];
  }

  // Ensure all string fields exist
  extracted.job_title = extracted.job_title || '';
  extracted.description = extracted.description || '';
  extracted.customer_name = extracted.customer_name || '';
  extracted.status = extracted.status || 'booked';

  return [{ json: { extracted } }];
} catch (err) {
  return [{ json: { error: 'Failed to parse AI response: ' + err.message } }];
}
